import itertools
import networkx as nx

def get_cyclic_distance(m):
    perms = list(itertools.permutations(range(m)))
    swaps = [(i, (i + 1) % m) for i in range(m)]
    G = nx.Graph()
    for p in perms:
        G.add_node(p)
        for s in swaps:
            p_list = list(p)
            p_list[s[0]], p_list[s[1]] = p_list[s[1]], p_list[s[0]]
            G.add_edge(p, tuple(p_list))
    def get_orbit(p):
        orbit = []
        curr = list(p)
        for _ in range(m):
            orbit.append(tuple(curr))
            curr = curr[1:] + [curr[0]]
        return tuple(sorted(orbit))
    orbits = set()
    for p in perms:
        orbits.add(get_orbit(p))
    orbit_list = list(orbits)
    orbit_to_idx = {orb: i for i, orb in enumerate(orbit_list)}
    G_orb = nx.Graph()
    for p in perms:
        u = orbit_to_idx[get_orbit(p)]
        for s in swaps:
            p_list = list(p)
            p_list[s[0]], p_list[s[1]] = p_list[s[1]], p_list[s[0]]
            v = orbit_to_idx[get_orbit(tuple(p_list))]
            G_orb.add_edge(u, v)
    return nx.diameter(G_orb)

print(f"m=7, n={get_cyclic_distance(7)}")

